// ─── Types ────────────────────────────────────────────────────────────────────

export type CronFieldName = 'minute' | 'hour' | 'day' | 'month' | 'weekday';

export interface FieldRange {
  min: number;
  max: number;
}

export const FIELD_RANGES: Record<CronFieldName, FieldRange> = {
  minute:  { min: 0,  max: 59 },
  hour:    { min: 0,  max: 23 },
  day:     { min: 1,  max: 31 },
  month:   { min: 1,  max: 12 },
  weekday: { min: 0,  max: 6  },
};

export const FIELD_LABELS: Record<CronFieldName, string> = {
  minute:  'Minute',
  hour:    'Hour',
  day:     'Day',
  month:   'Month',
  weekday: 'Weekday',
};

export const WEEKDAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
export const MONTH_NAMES   = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                               'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export type FieldMode = 'every' | 'specific' | 'range' | 'step';

export interface ParsedField {
  raw: string;
  mode: FieldMode;
  // specific: list of numbers
  values: number[];
  // range: from-to
  rangeFrom: number;
  rangeTo: number;
  // step: the N in */N or from/N
  step: number;
  stepBase: number; // 0 for *, or a specific base
}

export interface ParsedCron {
  fields: Record<CronFieldName, ParsedField>;
  valid: boolean;
  error: string | null;
}

// ─── Parsing ──────────────────────────────────────────────────────────────────

export function parseField(raw: string, fieldName: CronFieldName): ParsedField {
  const range = FIELD_RANGES[fieldName];
  const trimmed = raw.trim();

  // Every: *
  if (trimmed === '*') {
    return { raw: trimmed, mode: 'every', values: [], rangeFrom: range.min, rangeTo: range.max, step: 1, stepBase: 0 };
  }

  // Step: */N or base/N
  if (trimmed.includes('/')) {
    const [basePart, stepPart] = trimmed.split('/');
    const step = parseInt(stepPart, 10);
    const stepBase = basePart === '*' ? range.min : parseInt(basePart, 10);
    return {
      raw: trimmed,
      mode: 'step',
      values: [],
      rangeFrom: range.min,
      rangeTo: range.max,
      step: isNaN(step) ? 1 : step,
      stepBase: isNaN(stepBase) ? range.min : stepBase,
    };
  }

  // Range: N-M
  if (trimmed.includes('-')) {
    const [fromStr, toStr] = trimmed.split('-');
    const from = parseInt(fromStr, 10);
    const to   = parseInt(toStr, 10);
    return {
      raw: trimmed,
      mode: 'range',
      values: [],
      rangeFrom: isNaN(from) ? range.min : from,
      rangeTo:   isNaN(to)   ? range.max : to,
      step: 1,
      stepBase: 0,
    };
  }

  // Specific: comma-separated or single number
  const values = trimmed.split(',').map((s) => parseInt(s.trim(), 10)).filter((n) => !isNaN(n));
  return {
    raw: trimmed,
    mode: 'specific',
    values,
    rangeFrom: range.min,
    rangeTo: range.max,
    step: 1,
    stepBase: 0,
  };
}

const FIELD_ORDER: CronFieldName[] = ['minute', 'hour', 'day', 'month', 'weekday'];

export function parseCron(expression: string): ParsedCron {
  const parts = expression.trim().split(/\s+/);
  if (parts.length !== 5) {
    const emptyField: ParsedField = {
      raw: '*',
      mode: 'every',
      values: [],
      rangeFrom: 0,
      rangeTo: 59,
      step: 1,
      stepBase: 0,
    };
    return {
      fields: {
        minute:  { ...emptyField },
        hour:    { ...emptyField, rangeTo: 23 },
        day:     { ...emptyField, rangeFrom: 1, rangeTo: 31 },
        month:   { ...emptyField, rangeFrom: 1, rangeTo: 12 },
        weekday: { ...emptyField, rangeTo: 6 },
      },
      valid: false,
      error: 'Expected exactly 5 fields',
    };
  }

  const fields = {} as Record<CronFieldName, ParsedField>;
  for (let i = 0; i < 5; i++) {
    fields[FIELD_ORDER[i]] = parseField(parts[i], FIELD_ORDER[i]);
  }

  return { fields, valid: true, error: null };
}

// ─── Serialization ────────────────────────────────────────────────────────────

export function fieldToString(field: ParsedField): string {
  switch (field.mode) {
    case 'every':
      return '*';
    case 'step':
      return field.stepBase === 0 ? `*/${field.step}` : `${field.stepBase}/${field.step}`;
    case 'range':
      return `${field.rangeFrom}-${field.rangeTo}`;
    case 'specific':
      return field.values.length > 0 ? field.values.join(',') : '*';
    default:
      return '*';
  }
}

export function buildExpression(fields: Record<CronFieldName, ParsedField>): string {
  return FIELD_ORDER.map((f) => fieldToString(fields[f])).join(' ');
}

// ─── Matching ─────────────────────────────────────────────────────────────────

function getMatchingValues(field: ParsedField, fieldName: CronFieldName): number[] {
  const range = FIELD_RANGES[fieldName];
  const all = Array.from({ length: range.max - range.min + 1 }, (_, i) => i + range.min);

  switch (field.mode) {
    case 'every':
      return all;
    case 'specific':
      return field.values.filter((v) => v >= range.min && v <= range.max);
    case 'range': {
      const from = Math.max(field.rangeFrom, range.min);
      const to   = Math.min(field.rangeTo, range.max);
      return Array.from({ length: to - from + 1 }, (_, i) => i + from);
    }
    case 'step': {
      const result: number[] = [];
      for (let v = field.stepBase; v <= range.max; v += field.step) {
        if (v >= range.min) result.push(v);
      }
      return result;
    }
    default:
      return all;
  }
}

export function getNextRuns(expression: string, from: Date, count: number): Date[] {
  const parsed = parseCron(expression);
  if (!parsed.valid) return [];

  const minutes  = getMatchingValues(parsed.fields.minute,  'minute');
  const hours    = getMatchingValues(parsed.fields.hour,    'hour');
  const days     = getMatchingValues(parsed.fields.day,     'day');
  const months   = getMatchingValues(parsed.fields.month,   'month');
  const weekdays = getMatchingValues(parsed.fields.weekday, 'weekday');

  const results: Date[] = [];
  // Start from the next minute
  const cursor = new Date(from);
  cursor.setSeconds(0, 0);
  cursor.setMinutes(cursor.getMinutes() + 1);

  let iterations = 0;
  const MAX_ITER = 366 * 24 * 60; // safety limit: 1 year of minutes

  while (results.length < count && iterations < MAX_ITER) {
    iterations++;
    const m   = cursor.getMonth() + 1; // 1-12
    const d   = cursor.getDate();       // 1-31
    const h   = cursor.getHours();
    const min = cursor.getMinutes();
    const wd  = cursor.getDay();        // 0-6

    if (!months.includes(m)) {
      // Advance to the first day of the next matching month
      cursor.setDate(1);
      cursor.setHours(0, 0, 0, 0);
      cursor.setMonth(cursor.getMonth() + 1);
      continue;
    }
    if (!days.includes(d) || !weekdays.includes(wd)) {
      cursor.setDate(cursor.getDate() + 1);
      cursor.setHours(0, 0, 0, 0);
      continue;
    }
    if (!hours.includes(h)) {
      cursor.setHours(cursor.getHours() + 1, 0, 0, 0);
      continue;
    }
    if (!minutes.includes(min)) {
      cursor.setMinutes(cursor.getMinutes() + 1, 0, 0);
      continue;
    }

    results.push(new Date(cursor));
    cursor.setMinutes(cursor.getMinutes() + 1, 0, 0);
  }

  return results;
}

// ─── Human description ────────────────────────────────────────────────────────

function describeField(field: ParsedField, fieldName: CronFieldName): string {
  const label = FIELD_LABELS[fieldName].toLowerCase();
  switch (field.mode) {
    case 'every':
      return `every ${label}`;
    case 'step':
      return `every ${field.step} ${label}s`;
    case 'range':
      if (fieldName === 'weekday') {
        return `${WEEKDAY_NAMES[field.rangeFrom]} through ${WEEKDAY_NAMES[field.rangeTo]}`;
      }
      if (fieldName === 'month') {
        return `${MONTH_NAMES[field.rangeFrom - 1]} through ${MONTH_NAMES[field.rangeTo - 1]}`;
      }
      return `${label}s ${field.rangeFrom} through ${field.rangeTo}`;
    case 'specific': {
      if (field.values.length === 0) return `every ${label}`;
      if (fieldName === 'weekday') {
        return field.values.map((v) => WEEKDAY_NAMES[v]).join(', ');
      }
      if (fieldName === 'month') {
        return field.values.map((v) => MONTH_NAMES[v - 1]).join(', ');
      }
      if (fieldName === 'hour') {
        return field.values.map((v) => {
          const ampm = v < 12 ? 'am' : 'pm';
          const h = v % 12 === 0 ? 12 : v % 12;
          return `${h}${ampm}`;
        }).join(', ');
      }
      return `at ${label} ${field.values.join(', ')}`;
    }
    default:
      return `every ${label}`;
  }
}

export function describeExpression(expression: string): string {
  const parsed = parseCron(expression);
  if (!parsed.valid) return 'Invalid cron expression';

  const f = parsed.fields;

  // Special cases for common patterns
  const minStr  = fieldToString(f.minute);
  const hourStr = fieldToString(f.hour);
  const dayStr  = fieldToString(f.day);
  const monStr  = fieldToString(f.month);
  const wdStr   = fieldToString(f.weekday);

  // Every N minutes
  if (f.minute.mode === 'step' && hourStr === '*' && dayStr === '*' && monStr === '*' && wdStr === '*') {
    return `Every ${f.minute.step} minute${f.minute.step === 1 ? '' : 's'}`;
  }
  // Every hour on minute X
  if (f.minute.mode === 'specific' && f.minute.values.length === 1 && hourStr === '*') {
    const min = f.minute.values[0];
    if (min === 0) return `Every hour`;
    return `Every hour at ${min} minutes past`;
  }
  // Every N hours
  if (minStr === '0' && f.hour.mode === 'step' && dayStr === '*' && monStr === '*' && wdStr === '*') {
    return `Every ${f.hour.step} hours`;
  }
  // Daily at specific time
  if (f.minute.mode === 'specific' && f.hour.mode === 'specific' && dayStr === '*' && monStr === '*' && wdStr === '*') {
    const h = f.hour.values[0];
    const m = f.minute.values[0];
    const ampm = h < 12 ? 'AM' : 'PM';
    const hh = h % 12 === 0 ? 12 : h % 12;
    const mm = m.toString().padStart(2, '0');
    return `Daily at ${hh}:${mm} ${ampm}`;
  }
  // Weekdays
  if (f.minute.mode === 'specific' && f.hour.mode === 'specific' && dayStr === '*' && monStr === '*' && wdStr === '1-5') {
    const h = f.hour.values[0];
    const m = f.minute.values[0];
    const ampm = h < 12 ? 'AM' : 'PM';
    const hh = h % 12 === 0 ? 12 : h % 12;
    const mm = m.toString().padStart(2, '0');
    return `Weekdays at ${hh}:${mm} ${ampm}`;
  }

  // Generic description
  const parts: string[] = [];
  parts.push(describeField(f.minute, 'minute'));
  parts.push(describeField(f.hour, 'hour'));
  if (wdStr !== '*') {
    parts.push(describeField(f.weekday, 'weekday'));
  } else {
    parts.push(describeField(f.day, 'day'));
  }
  parts.push(describeField(f.month, 'month'));

  return parts.join(', ');
}

export function describeFieldHuman(field: ParsedField, fieldName: CronFieldName): string {
  return describeField(field, fieldName);
}
